-- Atomic opening edits reuse the established mutation lock; warehouse receipts keep their original guard.
DROP TRIGGER receipt_mutation_dependencies;
CREATE TRIGGER receipt_mutation_dependencies BEFORE INSERT ON receipt_mutation_locks WHEN NEW.mode<>'receive' AND NOT (EXISTS(SELECT 1 FROM document_drafts d WHERE d.id=NEW.document_id AND d.kind='opening' AND json_extract(d.header_json,'$.opening_mode')='in_use')) AND (
 EXISTS(SELECT 1 FROM stock_source_allocations a JOIN inventory_document_lines l ON l.id=a.source_line_id JOIN document_drafts d ON d.posted_inventory_id=l.document_id WHERE d.id=NEW.document_id)
 OR EXISTS(SELECT 1 FROM stock_cost_dependencies a JOIN inventory_document_lines l ON l.id=a.source_line_id JOIN document_drafts d ON d.posted_inventory_id=l.document_id WHERE d.id=NEW.document_id)
 OR EXISTS(SELECT 1 FROM inventory_document_lines l JOIN document_drafts d ON d.posted_inventory_id=l.document_id LEFT JOIN stock_lots s ON s.source_line_id=l.id WHERE d.id=NEW.document_id AND (s.source_line_id IS NULL OR s.remaining_quantity_milli<>s.initial_quantity_milli))
 OR EXISTS(SELECT 1 FROM document_draft_lines x JOIN inventory_document_lines l ON l.id=json_extract(x.line_json,'$.source_line_id') JOIN document_drafts d ON d.posted_inventory_id=l.document_id JOIN document_drafts other ON other.id=x.document_id WHERE d.id=NEW.document_id AND other.id<>d.id AND other.status<>'cancelled' AND other.deleted_at IS NULL)
) BEGIN SELECT RAISE(ABORT,'RECEIPT_HAS_DEPENDENCIES'); END;
CREATE TRIGGER opening_mutation_dependencies BEFORE INSERT ON receipt_mutation_locks WHEN EXISTS(SELECT 1 FROM document_drafts d WHERE d.id=NEW.document_id AND d.kind='opening' AND json_extract(d.header_json,'$.opening_mode')='in_use') AND (SELECT EXISTS(SELECT 1 FROM inventory_document_lines l WHERE l.document_id=d.posted_inventory_id AND (NOT EXISTS(SELECT 1 FROM opening_usage_lines ou WHERE ou.inventory_line_id=l.id) OR (SELECT count(*) FROM stock_usages u WHERE u.root_line_id=l.id)<>1 OR EXISTS(SELECT 1 FROM stock_usages u WHERE u.root_line_id=l.id AND (u.parent_usage_id IS NOT NULL OR u.open_quantity_milli<>u.quantity_milli)) OR EXISTS(SELECT 1 FROM stock_movements m WHERE m.document_line_id=l.id) OR EXISTS(SELECT 1 FROM stock_lots lot WHERE lot.source_line_id=l.id) OR EXISTS(SELECT 1 FROM stock_cost_dependencies c WHERE c.source_line_id=l.id OR c.consumer_line_id=l.id) OR EXISTS(SELECT 1 FROM stock_source_allocations a WHERE a.source_line_id=l.id OR a.consumer_line_id=l.id) OR EXISTS(SELECT 1 FROM inventory_valuation_flags f WHERE f.origin_line_id=l.id AND f.inventory_line_id<>l.id) OR EXISTS(SELECT 1 FROM equipment_operations e JOIN stock_usages u ON u.id=e.from_usage_id OR u.id=e.to_usage_id WHERE u.root_line_id=l.id) OR EXISTS(SELECT 1 FROM retread_jobs j WHERE j.send_line_id=l.id OR j.received_line_id=l.id) OR EXISTS(SELECT 1 FROM usage_serials us JOIN stock_usages u ON u.id=us.usage_id WHERE u.root_line_id=l.id AND (us.active<>1 OR NOT EXISTS(SELECT 1 FROM inventory_serials s WHERE s.part_id=us.part_id AND s.serial_key=us.serial_key AND s.document_line_id=l.id AND s.status='mounted'))) OR EXISTS(SELECT 1 FROM document_draft_lines dl JOIN document_drafts other ON other.id=dl.document_id JOIN stock_usages u ON u.id=json_extract(dl.line_json,'$.usage_id') WHERE u.root_line_id=l.id AND other.id<>d.id AND other.deleted_at IS NULL AND other.status<>'cancelled'))) FROM document_drafts d WHERE d.id=NEW.document_id) BEGIN SELECT RAISE(ABORT,'OPENING_HAS_DEPENDENCIES'); END;
CREATE TRIGGER opening_mutation_edit_only BEFORE INSERT ON receipt_mutation_locks WHEN EXISTS(SELECT 1 FROM document_drafts d WHERE d.id=NEW.document_id AND d.kind='opening' AND json_extract(d.header_json,'$.opening_mode')='in_use') AND NEW.mode<>'edit' BEGIN SELECT RAISE(ABORT,'OPENING_EDIT_ONLY'); END;
